        "heading": "Overview of Jarvis AI Assistant",
        "facts": [
          {
            "claim": "Jarvis AI Assistant is a voice dictation app that allows users to speak and have clean, punctuated text appear anywhere.",
            "evidence_id": "S1.4"
          },
          {
            "claim": "Jarvis AI Assistant is fully offline with local Whisper or NVIDIA Parakeet (via Sherpa-ONNX) support.",
            "evidence_id": "S1.45"
          },
          {
            "claim": "Jarvis AI Assistant is open source and has no tracking or telemetry.",
            "evidence_id": "S1.49"
          }
        ]
      },
      {
        "source_id": "S2",
        "heading": "Agent Manager and Provider Integration",
        "facts": [
          {
            "claim": "The AgentManager class initializes the UnifiedAgent with a provider, which can be Ollama, Gemini, or OpenAI.",
            "evidence_id": "S2.6"
          },
          {
            "claim": "The AgentManager supports Ollama as the primary provider and has limitations with Gemini and OpenAI.",
            "evidence_id": "S2.10"
          },
          {
            "claim": "The AgentManager logs debug and warning messages for provider initialization and key updates.",
            "evidence_id": "S2.17"
          }
        ]
      },
      {
        "source_id": "S3",
        "heading": "Unified Agent and Tool Execution",
        "facts": [
          {
            "claim": "The UnifiedAgent processes queries using either tool calling or text generation, depending on the provider's support.",
            "evidence_id": "S3.14"
          },
          {
            "claim": "The UnifiedAgent logs detailed information about query processing, tool execution, and response times.",
            "evidence_id": "S3.15"
          },
          {
            "claim": "The UnifiedAgent can generate text-only responses if tool calling is not supported.",
            "evidence_id": "S3.20"
          }
        ]
      },
      {
        "source_id": "S4",
        "heading": "Native React Agent and Tool Execution",
        "facts": [
          {
            "claim": "The NativeReact agent handles tool calls and results, appending them to messages for processing.",
            "evidence_id": "S4.8"
          },
          {
            "claim": "The agent checks for loop guards before executing tool calls to prevent infinite loops.",
            "evidence_id": "S4.9"
          },
          {
            "claim": "The agent returns results with metadata, including messages and tool results, after processing.",
            "evidence_id": "S4.16"
          }
        ]
      }
    ]
